/* MODULE kh03 · Bước 2 Hiểu khách hàng · Jobs-to-be-done: khách thuê sản phẩm để làm gì
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh03-01', skill:'insight', read:'6 phút', t:'Ly cà phê sữa đá 7 giờ sáng đang làm mấy việc cùng lúc?',
  situation:'Một quán cà phê mang đi gần khu văn phòng ở quận 3 bán 300 ly mỗi sáng. Chủ quán muốn tăng giá 3.000đ và định quảng cáo "cà phê nguyên chất, đậm vị". Nhân viên kể: nhiều khách chụp ly đặt lên bàn làm việc rồi đăng story, số khác uống vội trên xe, số khác nữa mua thêm một ly cho sếp.',
  concept:{ name:'Ba lớp của một việc: chức năng, cảm xúc, xã hội',
    body:'Khách "thuê" một sản phẩm để hoàn thành một việc, và việc đó thường có ba lớp. <b>Chức năng</b>: tỉnh táo, no bụng, đến nơi đúng giờ. <b>Cảm xúc</b>: thấy mình được thưởng, bớt căng thẳng, yên tâm. <b>Xã hội</b>: người khác nhìn mình thế nào — chăm chỉ, sành, biết quan tâm. Lớp chức năng dễ thấy nhất nên hay được quảng cáo, nhưng lớp cảm xúc và xã hội thường quyết định khách chịu trả thêm bao nhiêu.' },
  example:'Chủ quán hỏi nhanh 40 khách vì sao mua ở đây. 16 người nói "cho tỉnh" (chức năng), 14 người nói "tự thưởng cho buổi sáng" (cảm xúc), 10 người nói ly đẹp, mang lên văn phòng "trông có gu" hoặc mua mời đồng nghiệp (xã hội). Như vậy 24/40 = 60% khách đang thuê ly cà phê cho lớp cảm xúc và xã hội. Quảng cáo "đậm vị" chỉ nói với 40% còn lại.',
  takeaway:'Hỏi khách thuê sản phẩm để làm gì ở cả ba lớp: chức năng, cảm xúc và xã hội.',
  apply:'Chọn một món bạn mua hôm qua. Nói trong 60 giây: việc chức năng, việc cảm xúc và việc xã hội mà món đó làm giúp bạn.',
  mistakes:['Chỉ mô tả việc chức năng rồi dừng lại, bỏ quên lý do khách chịu trả thêm.','Nhầm việc xã hội với "khách thích sống ảo" rồi coi thường nó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khách trả thêm cho một ly cà phê đắt hơn ly vỉa hè chủ yếu vì điều gì?',
    options:[{k:'a',t:'Vì hạt cà phê ngon hơn hẳn, khách sành vị nhận ra ngay'},{k:'b',t:'Vì cảm giác tự thưởng và hình ảnh bản thân đi kèm ly cà phê'},
             {k:'c',t:'Vì quán đắt thì chắc vệ sinh an toàn thực phẩm tốt hơn'},{k:'d',t:'Vì khách không biết giá ly vỉa hè rẻ hơn bao nhiêu tiền'}],
    answer:'b', why:{a:'Phần lớn khách không phân biệt được hạt trong thử mù; vị chỉ là một phần nhỏ của khoản chênh.',
      b:'Đúng. Phần chênh giá thường trả cho lớp cảm xúc và xã hội, không chỉ cho việc tỉnh táo.',
      c:'An toàn là điều kiện cần, nhưng khách không trả gấp đôi chỉ vì điều đó.',
      d:'Khách biết rõ giá ly vỉa hè; họ vẫn chọn trả thêm.'} },
  { type:'mcq', stem:'Với kết quả 60% khách thuê ly cà phê cho lớp cảm xúc và xã hội, bạn chọn thông điệp nào để đi kèm việc tăng giá 3.000đ?',
    options:[{k:'a',t:'"Cà phê nguyên chất, đậm vị" vì đó là điều quán làm tốt nhất'},{k:'b',t:'"Giá tăng do nguyên liệu tăng" để khách thông cảm và chấp nhận'},
             {k:'c',t:'"Một ly cho buổi sáng của bạn" kèm ly mới đẹp, dễ mang mời đồng nghiệp'},{k:'d',t:'Giữ im lặng, tăng giá âm thầm từng ít một để khách quen không để ý và không phàn nàn'}],
    answer:'c', why:{a:'Chỉ nói với 40% khách thuê cho lớp chức năng; không lý giải được phần giá tăng.',
      b:'Giải thích chi phí khiến khách nghĩ về tiền, không nghĩ về giá trị họ nhận.',
      c:'Đúng. Thông điệp và bao bì phục vụ đúng việc cảm xúc và xã hội mà đa số khách thuê.',
      d:'Khách quen sẽ để ý; tăng giá mà không thêm lý do để trả thường gây phản ứng hơn.'} },
  { type:'calc', stem:'Hỏi 40 khách: 16 người thuê cà phê để tỉnh, 14 để tự thưởng, 10 để mang mời/khoe ở văn phòng. Bao nhiêu phần trăm khách thuê cho lớp cảm xúc hoặc xã hội?',
    unit:'%', ans:60, tol:0.1, wrong:[[40,'SAI_MAU_SO'],[35,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Cảm xúc + xã hội = 14 + 10 = 24 người.','24 ÷ 40 = 0,6 = <b>60%</b>.'] },
  { type:'mcq', stem:'Một phụ huynh mua bộ đồ chơi lắp ráp giá 900.000đ làm quà sinh nhật cho cháu. Việc xã hội ở đây là gì?',
    options:[{k:'a',t:'Giúp đứa trẻ phát triển tư duy không gian, khéo tay và kiên nhẫn khi tự lắp từng chi tiết'},{k:'b',t:'Được anh chị và đứa cháu thấy mình là người chú chu đáo, hào phóng'},
             {k:'c',t:'Cảm thấy vui khi nhìn đứa trẻ mở quà ngay trong buổi tiệc'},{k:'d',t:'Tìm được món quà nhanh, không phải đi nhiều cửa hàng'}],
    answer:'b', why:{a:'Đây là việc chức năng mà sản phẩm hứa với đứa trẻ.',
      b:'Đúng. Việc xã hội là hình ảnh của người mua trong mắt người khác.',
      c:'Đây là việc cảm xúc của chính người mua.',
      d:'Đây là việc chức năng của quá trình mua.'} },
  { type:'mcq', stem:'Một hãng nước suối chỉ quảng cáo "tinh khiết, đạt chuẩn". Đối thủ cùng giá nhưng bán ở gym với chai thiết kế thể thao. Vì sao đối thủ có thể thắng?',
    options:[{k:'a',t:'Vì nước của đối thủ chắc chắn tinh khiết hơn nước của hãng'},{k:'b',t:'Vì phòng gym ép khách phải mua đúng một loại nước duy nhất'},
             {k:'c',t:'Vì chai đẹp tốn nhiều tiền in ấn nên khách tin rằng nước bên trong cũng được lọc kỹ hơn'},{k:'d',t:'Vì họ phục vụ cả việc "trông như người sống khoẻ", không chỉ giải khát'}],
    answer:'d', why:{a:'Hai loại đều đạt chuẩn; khác biệt không nằm ở độ tinh khiết.',
      b:'Gym thường bán nhiều loại; khách vẫn chọn.',
      c:'Chi phí in không phải lý do khách tin; điều khách mua là hình ảnh bản thân.',
      d:'Đúng. Khi lớp chức năng ngang nhau, lớp xã hội và cảm xúc quyết định.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng một việc cảm xúc của người mua bảo hiểm sức khoẻ cho bố mẹ?',
    options:[{k:'a',t:'Được chi trả viện phí khi bố mẹ nằm viện'},{k:'b',t:'Được họ hàng thấy là người con có hiếu, biết lo xa cho bố mẹ'},
             {k:'c',t:'Ngủ yên hơn vì không còn lo một cơn bệnh làm cạn tiền'},{k:'d',t:'Giảm thuế thu nhập cá nhân nhờ khoản phí bảo hiểm đã đóng'}],
    answer:'c', why:{a:'Chi trả viện phí là việc chức năng.',
      b:'Được người khác nhìn nhận là việc xã hội.',
      c:'Đúng. Bớt lo âu là việc cảm xúc — thường là lý do thật khiến người ta ký.',
      d:'Đây là lợi ích tài chính, thuộc lớp chức năng.'} },
  { type:'mcq', stem:'Vì sao marketer mới hay chỉ viết về việc chức năng?',
    options:[{k:'a',t:'Vì nó dễ thấy, dễ đo và nằm sẵn trên bảng thông số sản phẩm'},{k:'b',t:'Vì khách hàng Việt Nam chỉ quan tâm công dụng thực tế, không quan tâm hình ảnh'},
             {k:'c',t:'Vì luật quảng cáo cấm nói về cảm xúc của người dùng'},{k:'d',t:'Vì việc cảm xúc chỉ quan trọng với hàng xa xỉ đắt tiền'}],
    answer:'a', why:{a:'Đúng. Lớp chức năng hiện ra ngay trong tài liệu sản phẩm; lớp cảm xúc và xã hội phải hỏi mới thấy.',
      b:'Ví dụ ly cà phê cho thấy đa số khách thuê cho lớp cảm xúc và xã hội.',
      c:'Luật cấm nói sai sự thật, không cấm nói về cảm xúc.',
      d:'Ly cà phê 35.000đ cũng mang việc cảm xúc; không riêng hàng xa xỉ.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh03-02', skill:'insight', read:'7 phút', t:'Cùng một người, vì sao sáng mua bánh mì mà tối lại gọi phở giao tận nhà?',
  situation:'Một chuỗi bánh mì ở Hà Nội thấy doanh số buổi sáng rất tốt nhưng buổi tối gần như bằng không, dù cùng một nhóm khách văn phòng. Trưởng marketing đề xuất giảm giá 20% sau 18 giờ. Trước khi duyệt, giám đốc hỏi: tối khách đang thuê cái gì thay cho bánh mì?',
  concept:{ name:'Hoàn cảnh quyết định lựa chọn',
    body:'Cùng một người, ở hoàn cảnh khác nhau, có việc khác nhau. JTBD luôn gắn với <b>khi nào, ở đâu, với ai, đang vội hay thong thả</b>. Buổi sáng trên xe máy, việc là "no nhanh, cầm một tay, không bẩn áo". Buổi tối ở nhà sau ngày dài, việc là "ăn một bữa nóng, tử tế, không phải nấu". Khi hoàn cảnh đổi, danh sách lựa chọn và tiêu chí chấm điểm đổi theo. Giảm giá không biến món ăn sáng thành bữa tối.' },
  example:'Chuỗi khảo sát 50 khách quen: 42 người mua bánh mì sáng vì "ăn trên đường, dưới 5 phút". Buổi tối, 35 người gọi cơm/phở giao tận nhà, 10 người nấu, 5 người ăn ngoài cùng gia đình. Không ai nhắc tới bánh mì. Giảm 20% không chạm vào việc buổi tối. Thay vào đó, chuỗi thử bán "bánh mì chảo" ăn tại chỗ cho nhóm đi làm về muộn và giữ giá.',
  takeaway:'Trước khi đổi giá, hỏi: trong hoàn cảnh này khách đang cố làm xong việc gì?',
  apply:'Chọn một sản phẩm quen thuộc. Mô tả hai hoàn cảnh dùng khác nhau và nói việc của khách ở mỗi hoàn cảnh trong 60 giây.',
  mistakes:['Coi khách là một hồ sơ nhân khẩu cố định, bỏ qua thời điểm và nơi chốn.','Dùng giảm giá để chữa một vấn đề về việc không khớp hoàn cảnh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao giảm giá bánh mì 20% sau 18 giờ có thể không kéo được khách?',
    options:[{k:'a',t:'Vì 20% là mức giảm quá nhỏ, phải giảm tới 50% mới đủ hấp dẫn khách văn phòng buổi tối'},{k:'b',t:'Vì khách không thấy thông báo giảm giá vào buổi tối'},
             {k:'c',t:'Vì bánh mì buổi tối kém tươi nên khách không tin chất lượng'},{k:'d',t:'Vì buổi tối khách có việc khác, bánh mì không nằm trong danh sách'}],
    answer:'d', why:{a:'Giảm sâu hơn vẫn không giải quyết việc khách cần một bữa tối nóng, tử tế.',
      b:'Có thể đúng một phần, nhưng kể cả thấy, khách vẫn không thuê bánh mì cho bữa tối.',
      c:'Độ tươi có thể là vấn đề nhỏ; lý do chính là việc khác nhau theo hoàn cảnh.',
      d:'Đúng. Hoàn cảnh đổi thì việc đổi, và bánh mì không được xét cho việc đó.'} },
  { type:'mcq', stem:'Bạn là giám đốc chuỗi bánh mì. Bạn chọn làm gì với doanh số buổi tối?',
    options:[{k:'a',t:'Duyệt giảm 20% sau 18 giờ và chạy thêm quảng cáo buổi tối'},{k:'b',t:'Thử một món phục vụ đúng việc "bữa tối nóng, ngồi ăn" ở vài cửa hàng'},
             {k:'c',t:'Đóng cửa sớm lúc 14 giờ để cắt toàn bộ chi phí nhân sự buổi tối'},{k:'d',t:'Làm lại logo và bao bì để trông sang hơn, hợp bữa tối'}],
    answer:'b', why:{a:'Giảm giá không đổi việc; bạn chỉ mất lãi trên số ít khách vẫn mua.',
      b:'Đúng. Phục vụ đúng việc của hoàn cảnh tối, thử nhỏ trước khi mở rộng.',
      c:'Có thể là lựa chọn hợp lý sau khi thử, nhưng bỏ cuộc trước khi hiểu việc thì phí cơ hội.',
      d:'Bao bì không biến món ăn nhanh thành bữa tối tử tế.'} },
  { type:'calc', stem:'Trong 50 khách quen, 35 người tối gọi cơm/phở giao tận nhà. Tỉ lệ này là bao nhiêu phần trăm?',
    unit:'%', ans:70, tol:0.1, wrong:[[35,'SAI_MAU_SO'],[83.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = 35 ÷ 50.','= 0,7 = <b>70%</b>.'] },
  { type:'mcq', stem:'Một hãng trà đóng chai bán tốt ở cửa hàng tiện lợi gần trường học lúc 11 giờ trưa nhưng kém ở siêu thị cuối tuần. Giả thuyết JTBD nào hợp lý nhất?',
    options:[{k:'a',t:'Trưa là việc "giải khát ngay, một mình"; cuối tuần là mua trữ cho cả nhà'},{k:'b',t:'Khách ở siêu thị giàu hơn nên chê trà đóng chai là rẻ tiền'},
             {k:'c',t:'Siêu thị để giá cao hơn cửa hàng tiện lợi nên cuối tuần khách quay sang hãng khác rẻ hơn'},{k:'d',t:'Cuối tuần trời mát hơn nên người ta ít uống nước giải khát'}],
    answer:'a', why:{a:'Đúng. Hai hoàn cảnh là hai việc: uống ngay và dự trữ cho gia đình, với tiêu chí khác nhau.',
      b:'Thu nhập không giải thích được vì cùng nhóm khách có thể đi cả hai nơi.',
      c:'Giá có thể chênh một chút nhưng chưa có dữ kiện; giả thuyết về việc giải thích rõ hơn.',
      d:'Thời tiết không đổi đều mỗi cuối tuần; đây là lời giải thích tiện tay.'} },
  { type:'mcq', stem:'Câu nào mô tả hoàn cảnh đủ cụ thể để thiết kế sản phẩm?',
    options:[{k:'a',t:'Nữ, 25–34 tuổi, sống ở thành phố lớn, thu nhập khá'},{k:'b',t:'Người thích sự tiện lợi và hiện đại trong cuộc sống hằng ngày'},
             {k:'c',t:'Khi đang kẹt xe lúc 7 giờ 30, bụng đói, chỉ còn một tay rảnh'},{k:'d',t:'Khách hàng trung thành đã mua ít nhất ba lần trong tháng qua'}],
    answer:'c', why:{a:'Đây là nhân khẩu học — không nói khách đang cố làm gì.',
      b:'Quá chung; ai cũng "thích tiện lợi".',
      c:'Đúng. Có thời điểm, trạng thái và ràng buộc — đủ để thiết kế món ăn cầm một tay.',
      d:'Đây là hành vi mua lặp lại, chưa nói gì về hoàn cảnh sử dụng.'} },
  { type:'mcq', stem:'Một quán trà sữa thấy đơn giao hàng tăng mạnh lúc 21–23 giờ. Thông tin nào giúp hiểu việc của khách nhất?',
    options:[{k:'a',t:'Độ tuổi trung bình và giới tính của người đặt'},{k:'b',t:'Họ đang làm gì lúc đặt: học bài, xem phim, hay làm thêm giờ'},
             {k:'c',t:'Món nào có biên lợi nhuận cao nhất trong khung giờ đó để quán đẩy mạnh quảng cáo'},{k:'d',t:'Ứng dụng giao hàng nào đang có phí giao rẻ nhất lúc đêm'}],
    answer:'b', why:{a:'Nhân khẩu không cho biết việc; hai bạn 20 tuổi có thể thuê trà sữa cho hai việc khác nhau.',
      b:'Đúng. Hoạt động lúc đặt chính là hoàn cảnh — nó cho biết khách cần tỉnh, cần vui hay cần thưởng.',
      c:'Biên lợi nhuận quan trọng cho quán, nhưng không nói gì về khách.',
      d:'Phí giao ảnh hưởng kênh, không giải thích vì sao họ muốn trà sữa lúc đó.'} },
  { type:'mcq', stem:'Vì sao cùng một khách lại "chấm điểm" sản phẩm khác nhau ở hai hoàn cảnh?',
    options:[{k:'a',t:'Vì khách hàng vốn thất thường, khó đoán, nên không nên tin lời họ nói trong khảo sát'},{k:'b',t:'Vì tâm trạng mỗi ngày khác nhau nên đánh giá dao động'},
             {k:'c',t:'Vì mỗi hoàn cảnh có ràng buộc riêng — thời gian, nơi chốn, người đi cùng'},{k:'d',t:'Vì đối thủ đổi khuyến mãi liên tục trong ngày'}],
    answer:'c', why:{a:'Họ không thất thường; họ nhất quán với việc của từng hoàn cảnh.',
      b:'Tâm trạng có ảnh hưởng, nhưng khác biệt sáng/tối lặp lại đều đặn là do hoàn cảnh.',
      c:'Đúng. Ràng buộc đổi thì tiêu chí đổi: sáng cần nhanh, tối cần tử tế.',
      d:'Khuyến mãi không giải thích một khuôn mẫu ổn định theo giờ.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh03-03', skill:'insight', read:'7 phút', t:'Ly cà phê buổi sáng thật ra đang cạnh tranh với những gì?',
  situation:'Một thương hiệu cà phê hoà tan lập danh sách đối thủ gồm ba hãng cà phê hoà tan khác và chỉ theo dõi giá của họ. Năm nay doanh số giảm 15% dù cả ba hãng kia cũng không tăng. Trợ lý thương hiệu được giao tìm xem "tiền của khách đã đi đâu".',
  concept:{ name:'Đối thủ theo việc, không theo ngành hàng',
    body:'Nếu việc là "tỉnh táo trong 30 phút đầu ngày làm việc", thì đối thủ không chỉ là cà phê hoà tan khác. Đó còn là ly cà phê mang đi, lon nước tăng lực, trà xanh đóng chai, thậm chí năm phút lướt điện thoại. JTBD vẽ lại bản đồ cạnh tranh: <b>mọi thứ khách có thể thuê cho cùng một việc</b> đều là đối thủ — kể cả "không làm gì". Nhìn theo ngành hàng, bạn chỉ thấy người giống mình; nhìn theo việc, bạn thấy người thật sự lấy khách.' },
  example:'Nhóm hỏi 200 người từng mua hoà tan mà năm nay mua ít đi. 90 người chuyển sang cà phê mang đi gần công ty, 50 người uống nước tăng lực, 30 người pha phin tại nhà, chỉ 30 người chuyển sang hoà tan hãng khác. Như vậy 170/200 = 85% khách bỏ đi không sang đối thủ cùng ngành. Danh sách theo dõi cũ chỉ nhìn thấy 15% câu chuyện.',
  takeaway:'Đối thủ thật là bất cứ thứ gì khách thuê cho cùng một việc, kể cả không làm gì.',
  apply:'Viết một việc của khách trong 1 câu, rồi kể ra năm thứ khách có thể thuê cho việc đó — ít nhất hai thứ khác ngành.',
  mistakes:['Lập danh sách đối thủ chỉ gồm hãng cùng ngành hàng.','Quên rằng "không làm gì" hoặc "tự làm" cũng là một lựa chọn cạnh tranh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khách bỏ cà phê hoà tan năm nay phần lớn đi đâu?',
    options:[{k:'a',t:'Sang các hãng cà phê hoà tan rẻ hơn đang chạy khuyến mãi'},{k:'b',t:'Sang những thứ khác ngành làm cùng việc tỉnh táo buổi sáng'},
             {k:'c',t:'Bỏ hẳn thói quen uống đồ có caffeine vì lý do sức khoẻ'},{k:'d',t:'Sang hàng nhập khẩu vì tin chất lượng cao hơn hàng nội'}],
    answer:'b', why:{a:'Chỉ 15% khách chuyển sang hoà tan hãng khác.',
      b:'Đúng. 85% chuyển sang cà phê mang đi, nước tăng lực, pha phin — cùng việc, khác ngành.',
      c:'Không có dữ kiện; phần lớn vẫn dùng caffeine dưới dạng khác.',
      d:'Hàng nhập vẫn là hoà tan, thuộc nhóm nhỏ 15%.'} },
  { type:'mcq', stem:'Bạn phụ trách thương hiệu hoà tan. Bạn sửa gì trong kế hoạch năm sau?',
    options:[{k:'a',t:'Giảm giá sâu hơn ba hãng hoà tan kia để giành lại thị phần ngành trong siêu thị và trên sàn'},{k:'b',t:'Tăng ngân sách quảng cáo gấp đôi với thông điệp cũ cho chắc'},
             {k:'c',t:'So sản phẩm với cà phê mang đi: nhanh hơn, rẻ hơn, pha ngay ở bàn làm việc'},{k:'d',t:'Ra thêm vị mới để khách hoà tan đang có mua nhiều hơn'}],
    answer:'c', why:{a:'Đánh nhau về giá với nhóm chỉ lấy 15% khách là nhắm sai chỗ.',
      b:'Thông điệp cũ không trả lời được vì sao khách chọn cà phê mang đi.',
      c:'Đúng. Đặt mình cạnh đối thủ thật theo việc và nói điểm thắng cho đúng việc đó.',
      d:'Vị mới có thể hay, nhưng không lấy lại 85% khách đã chuyển sang lựa chọn khác ngành.'} },
  { type:'calc', stem:'200 khách mua ít đi: 90 chuyển sang cà phê mang đi, 50 sang nước tăng lực, 30 pha phin tại nhà, 30 sang hoà tan hãng khác. Bao nhiêu phần trăm chuyển sang lựa chọn KHÁC ngành hoà tan?',
    unit:'%', ans:85, tol:0.1, wrong:[[15,'NHAM_TI_LE_ROI'],[45,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI','SAI_TINH_TOAN'],
    steps:['Khác ngành = 90 + 50 + 30 = 170 người.','170 ÷ 200 = <b>85%</b>.'] },
  { type:'mcq', stem:'Một trung tâm tiếng Anh cho người đi làm muốn biết đối thủ theo việc. Việc là "tự tin nói trong cuộc họp với sếp nước ngoài trong 3 tháng". Thứ nào KHÔNG phải đối thủ theo việc này?',
    options:[{k:'a',t:'Ứng dụng luyện nói với AI mỗi tối 15 phút'},{k:'b',t:'Một đồng nghiệp giỏi tiếng Anh ngồi cạnh để dịch hộ'},
             {k:'c',t:'Lớp luyện thi IELTS học thuật cho học sinh cấp 3'},{k:'d',t:'Chuẩn bị sẵn kịch bản và slide thật kỹ để nói ít đi'}],
    answer:'c', why:{a:'Ứng dụng AI được thuê cho đúng việc luyện nói — là đối thủ.',
      b:'Nhờ đồng nghiệp là cách "né việc" — vẫn cạnh tranh với trung tâm.',
      c:'Đúng. Luyện thi học thuật cho học sinh là việc khác, dù cùng ngành "tiếng Anh".',
      d:'Chuẩn bị kỹ để nói ít là một giải pháp thay thế thật, dù không tốn tiền.'} },
  { type:'mcq', stem:'Vì sao "không làm gì" cũng được tính là đối thủ?',
    options:[{k:'a',t:'Vì khách luôn có thể chịu đựng vấn đề thêm một thời gian thay vì trả tiền'},{k:'b',t:'Vì đó là cách nói hoa mỹ để marketer có thêm lý do xin ngân sách lớn hơn mỗi năm'},
             {k:'c',t:'Vì thống kê thị phần luôn phải cộng đủ 100% bằng một nhóm khác'},{k:'d',t:'Vì khách không mua nghĩa là họ không có nhu cầu gì cả'}],
    answer:'a', why:{a:'Đúng. Chịu đựng là lựa chọn miễn phí và quen thuộc — nhiều ngành thua chính nó.',
      b:'Đây là công cụ phân tích thật, không phải mẹo xin ngân sách.',
      c:'Không liên quan tới cách cộng thị phần.',
      d:'Có nhu cầu nhưng chọn chịu đựng — đó chính là lý do "không làm gì" là đối thủ.'} },
  { type:'mcq', stem:'Một hãng snack khoai tây thấy doanh số giảm khi các ứng dụng xem phim ngắn nở rộ. Cách đọc theo JTBD nào hợp lý?',
    options:[{k:'a',t:'Snack giảm vì người xem phim ngắn đều là giới trẻ đang ăn kiêng giữ dáng theo trào lưu'},{k:'b',t:'Đây là trùng hợp, vì phim và snack không cùng một ngành hàng'},
             {k:'c',t:'Ứng dụng đang chạy quảng cáo chê snack khoai tây'},{k:'d',t:'Cả hai cùng được thuê cho việc "giết thời gian rảnh, giải trí nhẹ"'}],
    answer:'d', why:{a:'Không có dữ kiện về ăn kiêng.',
      b:'Khác ngành nhưng có thể cùng việc — đúng điều JTBD chỉ ra.',
      c:'Không có căn cứ; đây là giả định vô cớ.',
      d:'Đúng. Hai thứ khác ngành có thể tranh cùng một khoảng thời gian và cùng một việc.'} },
  { type:'mcq', stem:'Danh sách đối thủ nào được lập theo việc "có bữa trưa no, sạch trong 30 phút nghỉ trưa ở văn phòng"?',
    options:[{k:'a',t:'Ba chuỗi cơm văn phòng lớn nhất trong thành phố'},{k:'b',t:'Cơm hộp mang từ nhà, quán cơm bình dân, đặt đồ ăn qua app, mì ly ở pantry'},
             {k:'c',t:'Các nhà hàng cao cấp và quán ăn gia đình phục vụ bữa trưa trong bán kính 5 km quanh toà nhà văn phòng'},{k:'d',t:'Các thương hiệu bán đồ ăn có mặt trên sàn thương mại điện tử'}],
    answer:'b', why:{a:'Chỉ cùng ngành; bỏ sót những lựa chọn lấy khách thật.',
      b:'Đúng. Mọi thứ khách có thể thuê cho đúng việc đó trong 30 phút, kể cả tự mang.',
      c:'Nhà hàng cao cấp không làm được việc "30 phút, rẻ, sạch".',
      d:'Theo kênh bán, không theo việc.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh03-04', skill:'comm', read:'6 phút', t:'Viết câu job thế nào để cả nhóm cùng hiểu một việc?',
  situation:'Buổi họp ra mắt ví điện tử cho sinh viên, mỗi người mô tả khách một kiểu: "Gen Z thích tiện", "sinh viên thiếu tiền", "người trẻ ghét tiền mặt". Sau hai tiếng, nhóm có 12 ý tưởng tính năng không liên quan nhau. Trưởng nhóm yêu cầu viết lại khách hàng thành đúng một câu có cấu trúc.',
  concept:{ name:'Câu job: "Khi…, tôi muốn…, để…"',
    body:'Một câu job tốt có ba phần. <b>Khi…</b> là hoàn cảnh cụ thể có thời điểm, trạng thái. <b>Tôi muốn…</b> là tiến triển khách cố đạt, viết bằng động từ, không nêu tên sản phẩm hay tính năng. <b>Để…</b> là kết quả sâu hơn, thường chứa lớp cảm xúc hoặc xã hội. Câu job giúp cả nhóm chấm mọi ý tưởng bằng một thước đo: ý tưởng này giúp khách làm việc đó tốt hơn không? Không giúp thì gạt.' },
  example:'Nhóm viết: "Khi đi ăn chung với 5 bạn cùng phòng cuối tháng, tôi muốn chia tiền nhanh và rõ ngay tại bàn, để không ai ngại nhắc nợ và tình bạn không sứt mẻ." Chấm 12 ý tưởng theo câu này: 4 ý giúp trực tiếp (chia hoá đơn, nhắc nợ lịch sự, quét QR nhóm, lịch sử chi chung), 8 ý bị gạt. Lượng việc cần làm giảm từ 12 còn 4, tức giảm 67%.',
  takeaway:'Câu job tốt có hoàn cảnh, tiến triển bằng động từ và kết quả sâu — không có tên sản phẩm.',
  apply:'Viết một câu "Khi…, tôi muốn…, để…" cho khách của sản phẩm bạn đang làm, rồi đọc to trong 60 giây và gạch mọi chữ là tên tính năng.',
  mistakes:['Viết tên tính năng vào phần "tôi muốn", ví dụ "tôi muốn có nút chia tiền".','Phần "khi" quá chung chung như "khi cần" hay "khi có nhu cầu".'],
  q:[
  { type:'mcq', stem:'Đoán trước: phần nào của câu job hay bị viết sai nhất?',
    options:[{k:'a',t:'Phần "để…", vì người viết thường quên kết quả cảm xúc'},{k:'b',t:'Phần chủ ngữ "tôi", vì nên viết là "khách hàng"'},
             {k:'c',t:'Phần "khi…", vì hay để chung chung kiểu "khi có nhu cầu"'},{k:'d',t:'Phần độ dài, vì câu job phải dưới 10 chữ mới dễ nhớ'}],
    answer:'c', why:{a:'Cũng hay sai, nhưng "khi" chung chung khiến cả câu vô dụng ngay từ đầu.',
      b:'Viết ngôi thứ nhất giúp nhóm đứng vào vị trí khách; không phải lỗi.',
      c:'Đúng. Không có hoàn cảnh cụ thể thì không thiết kế được gì.',
      d:'Không có giới hạn chữ; rõ quan trọng hơn ngắn.'} },
  { type:'mcq', stem:'Bạn phải chọn một câu job để dán lên tường phòng dự án ví điện tử. Bạn chọn câu nào?',
    options:[{k:'a',t:'"Khi ăn chung cuối tháng, tôi muốn chia tiền rõ ngay tại bàn, để không ai ngại nhắc nợ"'},{k:'b',t:'"Khi cần thanh toán, tôi muốn có một ví điện tử hiện đại với nhiều tính năng tiện ích, để tiện"'},
             {k:'c',t:'"Sinh viên 18–22 tuổi muốn ví điện tử có nút chia hoá đơn"'},{k:'d',t:'"Tôi muốn tiết kiệm tiền"'}],
    answer:'a', why:{a:'Đúng. Có hoàn cảnh cụ thể, tiến triển bằng động từ, và kết quả xã hội rõ.',
      b:'"Khi cần thanh toán" quá chung, và phần giữa nêu tên sản phẩm thay vì tiến triển.',
      c:'Đây là hồ sơ nhân khẩu cộng với một tính năng — không phải câu job.',
      d:'Thiếu hoàn cảnh và kết quả; ai cũng muốn tiết kiệm.'} },
  { type:'calc', stem:'Nhóm có 12 ý tưởng, sau khi chấm theo câu job giữ lại 4. Số ý tưởng giảm bao nhiêu phần trăm?',
    unit:'%', ans:66.7, tol:0.5, wrong:[[33.3,'NHAM_TI_LE_ROI'],[8,'NHAM_SO_TUYET_DOI']], errors:['NHAM_TI_LE_ROI','NHAM_SO_TUYET_DOI'],
    steps:['Giảm = 12 − 4 = 8 ý tưởng.','8 ÷ 12 = 0,667 ≈ <b>66,7%</b>.'] },
  { type:'mcq', stem:'Câu job nào viết phần "tôi muốn" đúng cách?',
    options:[{k:'a',t:'"…tôi muốn một chiếc máy lọc không khí có màn hình cảm ứng…"'},{k:'b',t:'"…tôi muốn thương hiệu uy tín, giá tốt và bảo hành dài…"'},
             {k:'c',t:'"…tôi muốn ứng dụng có chế độ tối và thông báo đẩy…"'},{k:'d',t:'"…tôi muốn biết không khí trong phòng con có an toàn không…"'}],
    answer:'d', why:{a:'Nêu sản phẩm và tính năng; khoá nhóm vào một giải pháp.',
      b:'Đây là tiêu chí chọn mua, không phải tiến triển khách muốn đạt.',
      c:'Toàn tính năng; không nói khách đang cố làm gì.',
      d:'Đúng. Viết bằng động từ về tiến triển, không gọi tên giải pháp.'} },
  { type:'mcq', stem:'Vì sao câu job không được chứa tên sản phẩm?',
    options:[{k:'a',t:'Vì luật sở hữu trí tuệ không cho viết tên thương hiệu trong tài liệu nội bộ'},{k:'b',t:'Vì khách không nhớ tên sản phẩm nên viết vào cũng vô ích'},
             {k:'c',t:'Vì câu job phải đúng cả khi giải pháp thay đổi, để so được mọi lựa chọn'},{k:'d',t:'Vì tên sản phẩm có thể đổi sau khi ra mắt nên sợ phải sửa'}],
    answer:'c', why:{a:'Không có luật nào như vậy.',
      b:'Khách nhớ hay không không phải lý do.',
      c:'Đúng. Việc bền hơn giải pháp; câu job trung lập cho phép so bạn với mọi thứ khách có thể thuê.',
      d:'Đổi tên là chuyện nhỏ; lý do thật là giữ câu job trung lập với giải pháp.'} },
  { type:'mcq', stem:'Một phòng khám nha khoa viết: "Khi con 7 tuổi bắt đầu thay răng, tôi muốn biết răng mọc có lệch không, để khỏi tốn tiền niềng sau này." Ý tưởng nào khớp câu job nhất?',
    options:[{k:'a',t:'Giảm 30% gói tẩy trắng răng cho phụ huynh đưa con đến khám trong tháng này'},{k:'b',t:'Gói khám định kỳ 6 tháng có ảnh chụp và báo cáo tiến trình mọc răng'},
             {k:'c',t:'Trang trí phòng chờ theo chủ đề hoạt hình cho trẻ nhỏ'},{k:'d',t:'Mở thêm chi nhánh ở trung tâm thương mại cho tiện gửi xe'}],
    answer:'b', why:{a:'Tẩy trắng phục vụ việc khác của người khác.',
      b:'Đúng. Giúp phụ huynh "biết răng có lệch không" và theo dõi để tránh niềng.',
      c:'Giúp trẻ đỡ sợ — việc phụ, không phải việc trong câu.',
      d:'Tiện lợi vị trí không giải quyết việc chính.'} },
  { type:'mcq', stem:'Nhóm có ba câu job khác nhau cho cùng sản phẩm. Nên xử lý thế nào?',
    options:[{k:'a',t:'Gộp ba câu thành một câu dài cho đủ ý, để ai trong nhóm cũng thấy ý của mình được giữ lại'},{k:'b',t:'Chọn câu nghe hay nhất để làm khẩu hiệu quảng cáo'},
             {k:'c',t:'Bỏ hết, quay lại mô tả khách theo độ tuổi và thu nhập cho đơn giản'},{k:'d',t:'Kiểm chứng với khách thật xem việc nào phổ biến và đau nhất rồi ưu tiên'}],
    answer:'d', why:{a:'Câu gộp mất tính cụ thể, không còn dùng để chấm ý tưởng.',
      b:'Câu job là công cụ nội bộ để quyết định, không phải khẩu hiệu.',
      c:'Quay về nhân khẩu là mất luôn thông tin về hoàn cảnh.',
      d:'Đúng. Nhiều việc là bình thường; ưu tiên bằng bằng chứng từ khách.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh03-05', skill:'measure', read:'7 phút', t:'Khách "sa thải" ứng dụng của bạn thì họ đang thuê gì thay thế?',
  situation:'Một ứng dụng quản lý chi tiêu cá nhân có 20.000 người tải trong tháng 3. Đến cuối tháng 4 chỉ còn 3.000 người mở ứng dụng ít nhất một lần mỗi tuần. Nhóm sản phẩm đang định thêm biểu đồ đẹp hơn và giao diện màu mới.',
  concept:{ name:'Phỏng vấn "sa thải": vì sao khách bỏ',
    body:'Khách bỏ sản phẩm là đã <b>sa thải</b> nó khỏi một việc, và thường đã thuê thứ khác thay. Hỏi người bỏ đi ba điều: <b>lúc nào</b> bạn ngừng dùng, lúc đó bạn đang cố làm gì, và <b>giờ bạn dùng gì thay</b>. Câu trả lời thường không phải "giao diện xấu" mà là "tốn công hơn cách cũ". Cái thay thế — sổ tay, ghi chú điện thoại, hay không theo dõi nữa — cho bạn biết việc thật và tiêu chuẩn phải vượt.' },
  example:'Nhóm gọi 30 người đã bỏ. 18 người nói nhập tay từng khoản quá mệt, giờ chỉ xem lịch sử ngân hàng; 7 người quay lại ghi chú điện thoại; 5 người thôi theo dõi. Không ai nhắc biểu đồ. Việc thật là "biết cuối tháng còn bao nhiêu mà không tốn công", và đối thủ là sao kê ngân hàng. Nhóm chuyển ưu tiên sang tự đọc thông báo biến động số dư.',
  takeaway:'Người bỏ đi cho bạn biết việc thật và thứ bạn phải thắng; hãy hỏi họ đang dùng gì thay.',
  apply:'Nghĩ về một ứng dụng bạn đã xoá. Nói trong 60 giây: lúc nào bạn bỏ, bạn đang cố làm gì, và giờ bạn dùng gì thay.',
  mistakes:['Chỉ khảo sát người đang dùng, không hỏi người đã bỏ.','Hỏi "bạn thấy tính năng nào cần cải thiện" thay vì hỏi họ dùng gì thay thế.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lý do phổ biến nhất khiến khách bỏ ứng dụng chi tiêu là gì?',
    options:[{k:'a',t:'Giao diện chưa đẹp, biểu đồ đơn điệu, màu sắc nhàm chán'},{k:'b',t:'Dùng tốn công hơn cách cũ họ đang có sẵn'},
             {k:'c',t:'Ứng dụng thiếu tính năng đầu tư chứng khoán và tiết kiệm'},{k:'d',t:'Họ lo ngại bị lộ dữ liệu tài chính cá nhân cho bên thứ ba'}],
    answer:'b', why:{a:'Không ai trong 30 người nhắc tới biểu đồ.',
      b:'Đúng. 18/30 bỏ vì nhập tay quá mệt so với xem sao kê.',
      c:'Thêm tính năng khác không giải quyết chuyện tốn công.',
      d:'Có thể là lo ngại của một số người, nhưng không nổi lên trong dữ liệu.'} },
  { type:'mcq', stem:'Bạn là trưởng sản phẩm. Với kết quả 30 cuộc gọi, bạn ưu tiên làm gì trong quý tới?',
    options:[{k:'a',t:'Làm lại giao diện màu mới và biểu đồ đẹp hơn như kế hoạch đã duyệt'},{k:'b',t:'Chạy quảng cáo kéo thêm 20.000 lượt tải để bù lượng người đã rời đi'},
             {k:'c',t:'Tự ghi khoản chi từ thông báo biến động số dư để bớt nhập tay'},{k:'d',t:'Tặng quà cho người mở app 7 ngày liên tục'}],
    answer:'c', why:{a:'Giải quyết vấn đề không ai nói tới.',
      b:'Đổ thêm khách vào một cái xô thủng; họ sẽ bỏ vì cùng lý do.',
      c:'Đúng. Đánh vào đúng lý do sa thải và vượt tiêu chuẩn của đối thủ thật là sao kê.',
      d:'Quà kéo mở app tạm thời, không làm việc bớt tốn công.'} },
  { type:'calc', stem:'Tháng 3 có 20.000 người tải; cuối tháng 4 còn 3.000 người dùng hằng tuần. Tỉ lệ người đã rời bỏ là bao nhiêu phần trăm?',
    unit:'%', ans:85, tol:0.1, wrong:[[15,'NHAM_TI_LE_ROI'],[17000,'NHAM_SO_TUYET_DOI']], errors:['NHAM_TI_LE_ROI','NHAM_SO_TUYET_DOI'],
    steps:['Rời bỏ = 20.000 − 3.000 = 17.000 người.','17.000 ÷ 20.000 = <b>85%</b>.'] },
  { type:'mcq', stem:'Câu hỏi nào hữu ích nhất khi phỏng vấn một người đã huỷ gói tập gym?',
    options:[{k:'a',t:'"Anh/chị chấm phòng tập bao nhiêu điểm trên thang 10?"'},{k:'b',t:'"Nếu giảm giá 20% thì anh/chị có quay lại đăng ký không?"'},
             {k:'c',t:'"Anh/chị thấy máy móc và huấn luyện viên có cần cải thiện gì?"'},{k:'d',t:'"Tuần cuối trước khi huỷ, anh/chị định tập lúc nào và giờ thay bằng gì?"'}],
    answer:'d', why:{a:'Điểm số không cho biết việc hay thứ thay thế.',
      b:'Câu giả định về giá cho câu trả lời lịch sự, ít tin được.',
      c:'Mời khách chê tính năng, dễ lạc khỏi việc thật.',
      d:'Đúng. Hỏi về khoảnh khắc thật và thứ đã được thuê thay thế.'} },
  { type:'mcq', stem:'Một người bỏ ứng dụng học từ vựng nói: "Giờ tôi xem phim có phụ đề tiếng Anh." Điều này cho biết gì?',
    options:[{k:'a',t:'Việc có thể là "tiến bộ tiếng Anh mà vẫn thấy vui", phim làm tốt hơn'},{k:'b',t:'Người này lười học và sẽ không bao giờ quay lại học tiếng Anh'},
             {k:'c',t:'Ứng dụng nên mua bản quyền phim để chiếu trong ứng dụng ngay'},{k:'d',t:'Phim là ngành khác nên không liên quan tới ứng dụng học từ vựng'}],
    answer:'a', why:{a:'Đúng. Thứ thay thế tiết lộ lớp cảm xúc của việc: học mà không thấy như học.',
      b:'Họ vẫn đang cố tiến bộ — chỉ đổi cách.',
      c:'Nhảy thẳng tới giải pháp đắt tiền khi mới có một câu trả lời.',
      d:'Khác ngành nhưng cùng việc — chính là đối thủ theo việc.'} },
  { type:'mcq', stem:'Vì sao khảo sát người đang dùng thường không phát hiện lý do khách bỏ?',
    options:[{k:'a',t:'Vì người đang dùng hay nói dối khi trả lời khảo sát online'},{k:'b',t:'Vì người đang dùng hài lòng nên họ chấm điểm quá cao, làm lệch trung bình'},
             {k:'c',t:'Vì họ là nhóm mà sản phẩm đang làm tốt việc; người bị bỏ rơi không có mặt'},{k:'d',t:'Vì khảo sát phải có ít nhất 1.000 người mới có ý nghĩa'}],
    answer:'c', why:{a:'Không phải nói dối; họ chỉ không trải qua điều khiến người khác bỏ.',
      b:'Điểm cao là hệ quả; vấn đề gốc là thiếu hẳn người đã bỏ trong mẫu.',
      c:'Đúng. Mẫu bị lệch về phía người sống sót; lý do sa thải nằm ở người đã rời.',
      d:'Cỡ mẫu không sửa được việc hỏi sai người.'} },
  { type:'mcq', stem:'Trong 30 người bỏ, 5 người "thôi theo dõi chi tiêu". Nên đọc nhóm này thế nào?',
    options:[{k:'a',t:'Họ chọn "không làm gì" — việc chưa đủ đau để trả công sức'},{k:'b',t:'Họ không phải khách mục tiêu, nên loại khỏi phân tích cho gọn số'},
             {k:'c',t:'Họ đã giàu lên nên không cần theo dõi tiền bạc nữa'},{k:'d',t:'Họ bỏ vì một lỗi kỹ thuật của ứng dụng mà nhóm chưa phát hiện'}],
    answer:'a', why:{a:'Đúng. "Không làm gì" là đối thủ; muốn thắng thì phải làm việc gần như không tốn công.',
      b:'Họ từng tải ứng dụng — họ có việc, chỉ là giải pháp chưa đáng.',
      c:'Không có dữ kiện nào nói vậy.',
      d:'Không ai nhắc lỗi kỹ thuật; đây là giả định vô cớ.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh03-06', skill:'insight', read:'7 phút', t:'Thêm tính năng mới hay làm tốt hơn việc khách đang thuê?',
  situation:'Một hãng nồi chiên không dầu đang bán mẫu 5 lít giá 2,5 triệu. Đội kỹ thuật đề xuất mẫu mới có 12 chế độ nấu, kết nối Wi-Fi, điều khiển qua app, giá 3,5 triệu. Bộ phận chăm sóc khách lại ghi nhận lời phàn nàn nhiều nhất là "khó rửa giỏ chiên".',
  concept:{ name:'Tính năng thừa và việc chưa làm tốt',
    body:'Khách không thuê tính năng, họ thuê kết quả. Mỗi việc có vài <b>tiêu chí thành công</b> khách tự đặt: nhanh, sạch, ít phải canh. Tính năng mới chỉ có giá trị khi giúp một tiêu chí đang <b>bị làm kém</b>. Nếu việc chính là "bữa tối giòn ngon trong 20 phút mà dọn dẹp nhẹ nhàng", thì 12 chế độ là thừa khi khâu rửa còn làm khách ngán. Thêm tính năng thừa làm sản phẩm đắt hơn, khó dùng hơn, mà không ai thuê nó nhiều hơn.' },
  example:'Hãng hỏi 100 chủ nồi: 72 người chỉ dùng 2 chế độ, 65 người phàn nàn khó rửa, 8 người muốn điều khiển qua app. Giỏ chống dính tháo rời, rửa được bằng máy làm tăng giá vốn 150.000đ; gói Wi-Fi và 12 chế độ tăng 700.000đ. Hãng chọn giỏ dễ rửa, bán giá 2,7 triệu, thông điệp "chiên xong, rửa trong 1 phút".',
  takeaway:'Trước khi thêm tính năng, tìm tiêu chí thành công nào của việc chính đang bị làm kém nhất.',
  apply:'Chọn một thiết bị trong nhà. Liệt kê tính năng bạn chưa bao giờ dùng và một điều khó chịu mỗi lần dùng. Nói trong 60 giây nên sửa gì trước.',
  mistakes:['Đo sức mạnh sản phẩm bằng số tính năng trên bảng so sánh.','Nghe đội kỹ thuật "làm được gì" thay vì nghe khách "đang khổ ở đâu".'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong 100 chủ nồi chiên, bao nhiêu người thường dùng quá 2 chế độ nấu?',
    options:[{k:'a',t:'Khoảng 70–80 người, vì ai mua nồi cũng muốn thử hết chế độ'},{k:'b',t:'Khoảng một nửa, vì nhà nào cũng nấu nhiều món khác nhau'},
             {k:'c',t:'Khoảng 90 người, vì các chế độ được in rõ trên thân nồi'},{k:'d',t:'Chỉ khoảng một phần tư; đa số dùng một, hai chế độ quen'}],
    answer:'d', why:{a:'Thử lúc đầu khác với dùng thường xuyên.',
      b:'Nấu nhiều món không có nghĩa dùng nhiều chế độ; nhiều người chỉnh tay nhiệt độ quen.',
      c:'In rõ không làm người ta dùng.',
      d:'Đúng. 72/100 chỉ dùng 2 chế độ, tức 28 người dùng nhiều hơn.'} },
  { type:'mcq', stem:'Bạn là giám đốc sản phẩm. Bạn chọn phương án nào cho mẫu nồi mới?',
    options:[{k:'a',t:'Giỏ tháo rời dễ rửa, giá 2,7 triệu, nói rõ "rửa trong 1 phút"'},{k:'b',t:'12 chế độ và Wi-Fi, giá 3,5 triệu, để bảng so sánh trên sàn luôn thắng đối thủ'},
             {k:'c',t:'Làm cả hai thứ, giá 3,7 triệu cho đủ đầy, ai muốn gì cũng có'},{k:'d',t:'Giữ nguyên mẫu cũ và giảm giá 10%'}],
    answer:'a', why:{a:'Đúng. Sửa đúng tiêu chí đang bị làm kém với chi phí thấp, giữ giá dễ mua.',
      b:'Chỉ 8% khách muốn app; bạn tăng giá 1 triệu cho thứ ít người thuê.',
      c:'Giá cao khiến mất phần lớn khách chỉ cần nồi dễ rửa.',
      d:'Giảm giá không làm khâu rửa bớt khổ.'} },
  { type:'calc', stem:'Mẫu cũ bán 2,5 triệu. Giỏ dễ rửa tăng giá vốn 150.000đ, mẫu mới bán 2,7 triệu. Phần giá bán tăng lớn hơn phần giá vốn tăng bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:50, tol:0.5, wrong:[[200,'QUEN_CHI_PHI_BIEN_DOI'],[350,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_BIEN_DOI','SAI_TINH_TOAN'],
    steps:['Giá bán tăng = 2.700 − 2.500 = 200 nghìn đồng.','Trừ giá vốn tăng: 200 − 150 = <b>50 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Một ứng dụng ngân hàng thêm mục xem tử vi, đặt vé xem phim, mua bảo hiểm. Đánh giá chuyển khoản vẫn là "hay lỗi OTP". Nhận định nào đúng theo JTBD?',
    options:[{k:'a',t:'Thêm tiện ích giúp giữ chân khách lâu hơn nên hướng đi là đúng'},{k:'b',t:'Lỗi OTP là do nhà mạng, ngân hàng không cần bận tâm nhiều'},
             {k:'c',t:'Việc chính là chuyển tiền nhanh và chắc; tiện ích không bù được'},{k:'d',t:'Khách phàn nàn OTP chỉ là số ít, không đại diện cho tất cả'}],
    answer:'c', why:{a:'Tiện ích phụ không giữ khách nếu việc chính hay trục trặc.',
      b:'Khách không phân biệt lỗi do ai; họ chỉ thấy ứng dụng không làm xong việc.',
      c:'Đúng. Việc chính bị làm kém thì tính năng mới là thừa trong mắt khách.',
      d:'Không có số liệu để gạt đi; phàn nàn lặp lại ở việc chính rất đáng lo.'} },
  { type:'mcq', stem:'Làm sao phân biệt tính năng "thừa" với tính năng "chưa ai nghĩ tới nhưng cần"?',
    options:[{k:'a',t:'Hỏi khách "bạn có muốn tính năng X không" và đếm số người gật đầu'},{k:'b',t:'Xem nó giúp một tiêu chí thành công của việc chính đang bị làm kém'},
             {k:'c',t:'Xem đối thủ đã có chưa; đối thủ có rồi thì là cần, chưa có là thừa'},{k:'d',t:'Để đội kỹ thuật quyết vì họ hiểu công nghệ khả thi nhất'}],
    answer:'b', why:{a:'Hỏi "có muốn không" thì ai cũng gật; không đo được giá trị thật.',
      b:'Đúng. Gắn tính năng vào một tiêu chí đang bị làm kém là phép thử rõ ràng nhất.',
      c:'Chạy theo đối thủ dễ sao chép luôn tính năng thừa của họ.',
      d:'Khả thi kỹ thuật không trả lời câu hỏi khách có thuê nó không.'} },
  { type:'mcq', stem:'Một hãng máy giặt quảng cáo "22 chương trình giặt". Khách phàn nàn giặt xong quần áo vẫn nhăn, mất công ủi. Bạn đề xuất gì?',
    options:[{k:'a',t:'Chạy quảng cáo nhấn mạnh con số 22 chương trình cho mạnh hơn nữa'},{k:'b',t:'Thêm lên 30 chương trình để vượt hẳn đối thủ trên bảng so sánh'},
             {k:'c',t:'Tặng kèm bàn ủi để khách tự giải quyết nếp nhăn'},{k:'d',t:'Cải tiến chế độ hơi nước giảm nhăn và nói về "bớt ủi"'}],
    answer:'d', why:{a:'Nói nhiều hơn về thứ khách không cần.',
      b:'Thêm chương trình thừa, không chạm vào điều khách khổ.',
      c:'Đẩy việc về cho khách; vẫn phải ủi.',
      d:'Đúng. Đánh vào tiêu chí "không phải ủi" của việc giặt đồ.'} },
  { type:'mcq', stem:'Vì sao tính năng thừa có thể làm hại sản phẩm, không chỉ vô ích?',
    options:[{k:'a',t:'Vì nó tăng giá và độ phức tạp, đẩy đi người chỉ cần việc chính'},{k:'b',t:'Vì đối thủ sẽ sao chép ngay và kiện vi phạm bản quyền thiết kế'},
             {k:'c',t:'Vì khách sẽ nghĩ sản phẩm là hàng nhái, kém chất lượng'},{k:'d',t:'Vì kênh bán hàng từ chối nhận sản phẩm có quá nhiều tính năng'}],
    answer:'a', why:{a:'Đúng. Khách trả thêm tiền và công học cách dùng cho thứ họ không thuê.',
      b:'Sao chép không phải hệ quả của tính năng thừa.',
      c:'Nhiều tính năng không làm khách nghĩ là hàng nhái.',
      d:'Kênh bán thường không từ chối vì lý do này.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh03-07', skill:'brand', read:'6 phút', t:'Đặt tên và viết thông điệp theo việc của khách thế nào?',
  situation:'Một hãng sữa chua uống ra dòng mới đóng chai 150ml, có men vi sinh. Ba tên được đề xuất: "ProBio Max 150", "Sữa chua uống men sống" và "Nhẹ bụng sau bữa". Ngân sách chỉ đủ thử hai phiên bản bao bì ở 40 cửa hàng tiện lợi trong 4 tuần.',
  concept:{ name:'Tên và thông điệp gọi đúng việc',
    body:'Khi khách đứng trước kệ vài giây, cái tên và dòng chữ lớn nhất trên bao bì phải <b>trả lời việc họ đang có</b>: "cái này giúp tôi làm xong chuyện gì?". Tên kỹ thuật như "ProBio Max" nói về sản phẩm; tên theo việc như "Nhẹ bụng sau bữa" nói về khách. Thông điệp theo việc cũng chỉ ra luôn <b>hoàn cảnh dùng</b> — sau bữa trưa, trên đường đi làm — giúp khách nhớ ra đúng lúc cần mua. Tên theo việc không cần sáng tạo lạ; nó cần khiến khách nhận ra mình.' },
  example:'Hãng thử hai bao bì, mỗi bản ở 20 cửa hàng. Sau 4 tuần, bản "ProBio Max 150" bán 1.600 chai, bản "Nhẹ bụng sau bữa" bán 2.400 chai. Doanh số bản theo việc cao hơn 50%. Khi hỏi khách mua, nhiều người nói "tôi hay đầy bụng sau bữa trưa ở công ty". Hãng giữ tên theo việc và đặt thêm quầy gần khu cơm văn phòng.',
  takeaway:'Tên tốt khiến khách nhận ra việc của mình trong vài giây, không bắt họ giải mã kỹ thuật.',
  apply:'Lấy một sản phẩm có tên kỹ thuật. Viết lại một cái tên hoặc một dòng chữ bao bì gọi đúng việc và hoàn cảnh dùng, rồi đọc to trong 60 giây.',
  mistakes:['Đặt tên theo thành phần hay công nghệ vì đội nội bộ thấy nó "xịn".','Viết thông điệp chung chung "tốt cho sức khoẻ" không gọi ra hoàn cảnh nào.'],
  q:[
  { type:'mcq', stem:'Đoán trước: giữa "ProBio Max 150" và "Nhẹ bụng sau bữa", tên nào bán tốt hơn ở cửa hàng tiện lợi?',
    options:[{k:'a',t:'"ProBio Max 150", vì nghe khoa học và cao cấp hơn'},{k:'b',t:'Hai tên bán ngang nhau vì cùng sản phẩm, cùng giá'},
             {k:'c',t:'"Nhẹ bụng sau bữa", vì khách nhận ra ngay việc của mình'},{k:'d',t:'"ProBio Max 150", vì tên tiếng Anh hợp giới trẻ thành thị'}],
    answer:'c', why:{a:'Nghe khoa học nhưng khách phải tự dịch ra lợi ích.',
      b:'Cùng sản phẩm, nhưng tên quyết định khách có dừng lại hay không.',
      c:'Đúng. Bản theo việc bán 2.400 so với 1.600 chai.',
      d:'Tên tiếng Anh không bù được việc không rõ.'} },
  { type:'mcq', stem:'Bạn chỉ được thử hai phiên bản bao bì. Bạn chọn cặp nào để thử?',
    options:[{k:'a',t:'"ProBio Max 150" và "Sữa chua uống men sống" vì đều nói rõ thành phần'},{k:'b',t:'Cùng tên "ProBio Max 150", hai màu bao bì khác nhau để xem màu nào bắt mắt hơn trên kệ lạnh'},
             {k:'c',t:'"Nhẹ bụng sau bữa" và một tên kỹ thuật, để so tên theo việc với tên theo sản phẩm'},{k:'d',t:'Không thử, chọn tên sếp thích nhất'}],
    answer:'c', why:{a:'Cả hai đều nói về sản phẩm; bài thử không trả lời được câu hỏi chính.',
      b:'Thử màu trước khi chốt cách gọi tên là thử chi tiết nhỏ trước quyết định lớn.',
      c:'Đúng. So trực tiếp hai cách gọi — theo việc và theo sản phẩm — để biết hướng nào thắng.',
      d:'Có ngân sách thử mà không dùng là bỏ phí bằng chứng.'} },
  { type:'calc', stem:'Bản "ProBio Max 150" bán 1.600 chai, bản "Nhẹ bụng sau bữa" bán 2.400 chai, mỗi bản ở 20 cửa hàng. Bản theo việc bán cao hơn bao nhiêu phần trăm?',
    unit:'%', ans:50, tol:0.1, wrong:[[33.3,'SAI_MAU_SO'],[800,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Chênh lệch = 2.400 − 1.600 = 800 chai.','So với bản gốc: 800 ÷ 1.600 = <b>50%</b>.'] },
  { type:'mcq', stem:'Một trung tâm tiếng Anh cho người đi làm đổi tên khoá "Business English Level B1" sang "Tự tin họp với đối tác nước ngoài trong 12 tuần". Vì sao tên mới có thể tốt hơn?',
    options:[{k:'a',t:'Vì tên dài hơn thì trông chuyên nghiệp, tốn nhiều công sức hơn'},{k:'b',t:'Vì bỏ chữ tiếng Anh giúp người học đỡ sợ trước khi đăng ký'},
             {k:'c',t:'Vì con số 12 tuần tạo cảm giác khẩn cấp, thúc khách đăng ký nhanh trước khi lớp đầy chỗ'},{k:'d',t:'Vì nó gọi đúng hoàn cảnh và tiến triển khách muốn, thay vì cấp độ'}],
    answer:'d', why:{a:'Độ dài không phải lý do; nhiều tên dài vẫn vô nghĩa.',
      b:'Tên mới vẫn nói về tiếng Anh; điểm khác là nó gọi ra việc.',
      c:'12 tuần cho biết thời hạn tiến triển, không phải mẹo khẩn cấp.',
      d:'Đúng. "B1" là ngôn ngữ của trung tâm; "họp với đối tác" là việc của khách.'} },
  { type:'mcq', stem:'Thông điệp nào của một hãng khăn ướt gọi đúng việc và hoàn cảnh nhất?',
    options:[{k:'a',t:'"Khăn ướt cao cấp, 99% nước tinh khiết, không cồn"'},{k:'b',t:'"Lau sạch tay bé sau bữa ăn dặm, không cần tìm bồn rửa"'},
             {k:'c',t:'"Thương hiệu được hàng triệu bà mẹ Việt Nam tin dùng mỗi ngày"'},{k:'d',t:'"Sự lựa chọn hoàn hảo cho cả gia đình bạn"'}],
    answer:'b', why:{a:'Nói về thành phần; khách phải tự nghĩ ra lúc nào dùng.',
      b:'Đúng. Có hoàn cảnh (sau ăn dặm, không có bồn rửa) và kết quả rõ.',
      c:'Bằng chứng xã hội; không nói việc cụ thể.',
      d:'Chung chung, áp vào sản phẩm nào cũng được.'} },
  { type:'mcq', stem:'Rủi ro khi đặt tên theo một việc quá hẹp là gì?',
    options:[{k:'a',t:'Khách có việc khác gần đó có thể nghĩ sản phẩm không dành cho họ'},{k:'b',t:'Tên theo việc luôn bị cơ quan quản lý từ chối đăng ký nhãn hiệu'},
             {k:'c',t:'Khách sẽ nghi ngờ vì tên quá dễ hiểu, không có gì bí ẩn'},{k:'d',t:'Đối thủ sẽ không thể cạnh tranh nên thị trường kém sôi động'}],
    answer:'a', why:{a:'Đúng. Tên hẹp đổi lấy độ rõ; cần cân nhắc việc chính có đủ lớn không.',
      b:'Không có quy định như vậy; tên mô tả thuần có thể khó bảo hộ, nhưng không phải luôn bị từ chối.',
      c:'Dễ hiểu là ưu điểm ở kệ hàng.',
      d:'Đây không phải rủi ro cho hãng.'} },
  { type:'mcq', stem:'Sau khi chọn tên "Nhẹ bụng sau bữa", hãng nên đặt thêm hàng ở đâu?',
    options:[{k:'a',t:'Quầy sữa ở siêu thị lớn, cạnh các loại sữa tươi gia đình để tận dụng lượng khách đông cuối tuần'},{k:'b',t:'Cửa hàng mẹ và bé vì sữa chua tốt cho trẻ nhỏ'},
             {k:'c',t:'Gần khu cơm văn phòng và quầy tính tiền cửa hàng tiện lợi buổi trưa'},{k:'d',t:'Phòng gym, vì người tập hay quan tâm tới sức khoẻ'}],
    answer:'c', why:{a:'Mua trữ cho gia đình là hoàn cảnh khác, không phải lúc "sau bữa".',
      b:'Không khớp việc người lớn đầy bụng sau bữa trưa.',
      c:'Đúng. Đặt hàng đúng nơi và đúng lúc hoàn cảnh của việc xảy ra.',
      d:'Quan tâm sức khoẻ chung, không phải hoàn cảnh sau bữa ăn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh03-08', skill:'creative', read:'7 phút', t:'Người ta đăng ký phòng gym để làm việc gì — và vì sao tháng thứ ba bỏ?',
  situation:'Một phòng gym ở Đà Nẵng bán gói 12 tháng giá 6 triệu. Tháng 1 có 300 hội viên mới. Đến tháng 4, chỉ 90 người còn đến ít nhất hai buổi mỗi tuần. Quảng cáo hiện tại là ảnh máy tập hiện đại và dòng chữ "Trang thiết bị nhập khẩu 100%".',
  concept:{ name:'JTBD cho dịch vụ: việc là sự thay đổi của chính khách',
    body:'Với dịch vụ, khách không thuê máy móc hay giáo trình; họ thuê một <b>sự thay đổi ở chính mình</b>: "mặc lại vừa chiếc quần cũ trước đám cưới bạn", "nói được với khách nước ngoài". Dịch vụ thắng khi giúp khách thấy <b>tiến bộ sớm</b> và vượt qua những lúc muốn bỏ. Phần khó của việc thường không nằm ở giờ tập mà ở ngoài giờ: lịch bận, ngại đi một mình, không thấy thay đổi. Quảng cáo nói về máy là nói về công cụ, không nói về sự thay đổi.' },
  example:'Phòng gym hỏi 60 người đã ngừng đến: 27 người nói "không thấy thay đổi gì sau 6 tuần", 18 người "không có ai đi cùng, ngại", 15 người "lịch làm thay đổi". Phòng thử gói mới cho 100 hội viên: đo cơ thể mỗi 2 tuần, ghép cặp bạn tập, lịch tập lại linh hoạt. Sau 3 tháng, 55 người trong nhóm thử còn đều đặn, so với 30% ở nhóm cũ.',
  takeaway:'Dịch vụ bán sự thay đổi của khách; hãy thiết kế cho những lúc họ muốn bỏ.',
  apply:'Nghĩ về một dịch vụ bạn từng bỏ dở. Nói trong 60 giây: bạn thuê nó cho sự thay đổi nào, và điều gì khiến bạn bỏ.',
  mistakes:['Quảng cáo dịch vụ bằng cơ sở vật chất thay vì sự thay đổi khách muốn.','Coi việc khách bỏ là do khách lười, không phải do dịch vụ chưa đỡ họ qua lúc khó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lý do hàng đầu hội viên gym bỏ tập sau vài tháng là gì?',
    options:[{k:'a',t:'Máy tập cũ, thiếu máy mới so với phòng gym đối thủ gần đó'},{k:'b',t:'Không thấy cơ thể thay đổi sau vài tuần tập'},
             {k:'c',t:'Phí gói tập quá cao so với thu nhập ở Đà Nẵng'},{k:'d',t:'Huấn luyện viên không đủ trình độ chuyên môn cao'}],
    answer:'b', why:{a:'Không ai trong 60 người nhắc tới máy.',
      b:'Đúng. 27/60 bỏ vì không thấy thay đổi — việc chính không được làm xong.',
      c:'Họ đã trả trước; phí không phải lý do ngừng đến.',
      d:'Không nổi lên trong dữ liệu.'} },
  { type:'mcq', stem:'Bạn là quản lý phòng gym. Bạn sửa gì trong chiến dịch tháng 1 năm sau?',
    options:[{k:'a',t:'Giữ ảnh máy tập nhập khẩu, thêm chữ "Giảm 30% cho 100 người đầu tiên đăng ký gói 12 tháng" thật nổi bật'},{k:'b',t:'Thuê người nổi tiếng chụp ảnh với máy tập để tăng độ nhận biết'},
             {k:'c',t:'Tăng số hội viên mới lên 500 để bù cho người bỏ giữa chừng'},{k:'d',t:'Bán gói "thấy thay đổi trong 8 tuần": đo định kỳ, bạn tập cùng, lịch linh hoạt'}],
    answer:'d', why:{a:'Giảm giá kéo thêm người sẽ bỏ vì cùng lý do.',
      b:'Vẫn nói về công cụ, không nói về sự thay đổi.',
      c:'Đổ thêm người vào vòng bỏ cuộc; chi phí tìm khách tăng mà giữ chân không đổi.',
      d:'Đúng. Bán đúng việc và thiết kế cho ba lý do bỏ đã biết.'} },
  { type:'calc', stem:'Nhóm thử 100 hội viên: sau 3 tháng còn 55 người tập đều. Nhóm cũ có tỉ lệ 30%. Nhóm thử cao hơn nhóm cũ bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:25, tol:0.1, wrong:[[83.3,'NHAM_DIEM_PHAN_TRAM'],[55,'SAI_TINH_TOAN']], errors:['NHAM_DIEM_PHAN_TRAM','SAI_TINH_TOAN'],
    steps:['Tỉ lệ nhóm thử = 55 ÷ 100 = 55%.','Chênh lệch = 55% − 30% = <b>25 điểm phần trăm</b>.'] },
  { type:'calc', stem:'Tháng 1 có 300 hội viên mới, đến tháng 4 còn 90 người đến đều. Tỉ lệ còn tập đều là bao nhiêu phần trăm?',
    unit:'%', ans:30, tol:0.1, wrong:[[70,'NHAM_TI_LE_ROI'],[210,'NHAM_SO_TUYET_DOI']], errors:['NHAM_TI_LE_ROI','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = 90 ÷ 300.','= <b>30%</b>.'] },
  { type:'mcq', stem:'Một trung tâm tiếng Anh thấy học viên bỏ nhiều ở tuần 5–6. Thiết kế nào khớp JTBD nhất?',
    options:[{k:'a',t:'Cho học viên nói một đoạn ngắn ở tuần 4 và so với bản ghi âm tuần 1'},{k:'b',t:'Tăng số bài tập về nhà để học viên có nhiều thứ phải làm hơn'},
             {k:'c',t:'Chuyển toàn bộ giáo viên sang người bản ngữ để học viên thêm tin'},{k:'d',t:'Giảm học phí khoá sau để học viên thấy được tri ân sau khoá học'}],
    answer:'a', why:{a:'Đúng. Cho khách thấy tiến bộ đúng lúc họ hay nản.',
      b:'Thêm gánh nặng đúng lúc khách đang muốn bỏ.',
      c:'Đổi công cụ, chưa chắc giúp khách thấy mình thay đổi.',
      d:'Giảm giá khoá sau không giữ được người đang nản ở khoá này.'} },
  { type:'mcq', stem:'Vì sao "không có ai đi cùng, ngại" được tính là một phần của việc, không phải chuyện riêng của khách?',
    options:[{k:'a',t:'Vì phòng gym có trách nhiệm pháp lý với cảm xúc của khách'},{k:'b',t:'Vì đó là lý do phổ biến nhất trong khảo sát 60 người'},
             {k:'c',t:'Vì việc có lớp cảm xúc và xã hội; ngại là rào cản dịch vụ có thể gỡ'},{k:'d',t:'Vì người đi tập một mình thường tập sai kỹ thuật, dễ chấn thương và phải nghỉ tập dài ngày'}],
    answer:'c', why:{a:'Không phải chuyện pháp lý.',
      b:'Lý do phổ biến nhất là không thấy thay đổi (27), không phải ngại (18).',
      c:'Đúng. Dịch vụ tốt thiết kế cả phần cảm xúc — ghép bạn tập là một cách.',
      d:'Có thể đúng nhưng không phải lý do khách đưa ra.'} },
  { type:'mcq', stem:'Một spa quảng cáo "máy công nghệ Hàn Quốc đời mới". Theo JTBD, thông điệp nào tốt hơn?',
    options:[{k:'a',t:'"Đầu tư 2 tỉ đồng cho hệ thống máy móc hiện đại nhất thành phố"'},{k:'b',t:'"Da đều màu hơn trước ngày cưới, có ảnh đo tiến bộ mỗi tuần"'},
             {k:'c',t:'"Đội ngũ chuyên viên được đào tạo bài bản tại Hàn Quốc"'},{k:'d',t:'"Không gian sang trọng, thư giãn tuyệt đối cho phái đẹp"'}],
    answer:'b', why:{a:'Nói về đầu tư của spa, không phải thay đổi của khách.',
      b:'Đúng. Có hoàn cảnh (trước ngày cưới), sự thay đổi và cách thấy tiến bộ.',
      c:'Nói về công cụ con người, không nói kết quả.',
      d:'Lớp cảm xúc chung chung, không gắn việc cụ thể.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kh03-09', skill:'measure', read:'7 phút', t:'Chọn việc nào để tập trung khi khách thuê bạn cho nhiều việc khác nhau?',
  situation:'Một thương hiệu bánh quy yến mạch có ngân sách quảng cáo 600 triệu cho quý tới. Khảo sát cho thấy khách thuê bánh cho ba việc: bữa sáng vội, ăn vặt giữa giờ làm, và làm quà biếu. Mỗi nhóm muốn một thông điệp khác. Giám đốc muốn chia đều 200 triệu mỗi việc.',
  concept:{ name:'Ưu tiên việc theo quy mô và mức chưa thoả mãn',
    body:'Khi sản phẩm được thuê cho nhiều việc, đừng chia đều. Chấm mỗi việc theo hai trục: <b>bao nhiêu người có việc đó</b> và <b>các lựa chọn hiện có đang làm việc đó kém tới đâu</b>. Việc lớn mà ai cũng đã làm tốt thì khó chen; việc nhỏ mà chưa ai làm tốt có thể là cửa ngách; việc vừa lớn vừa chưa được thoả mãn là nơi dồn tiền. Chia đều ngân sách cho mọi việc thường khiến không việc nào đủ tiếng nói để khách nhớ.' },
  example:'Khảo sát 500 người mua: 250 người thuê bánh cho bữa sáng vội, 175 người cho ăn vặt giữa giờ, 75 người làm quà. Điểm "chưa hài lòng với lựa chọn hiện có" trên thang 10: bữa sáng 7, ăn vặt 4, quà 3. Nhóm dồn 420 triệu, tức 70% ngân sách, vào việc bữa sáng vội; 180 triệu còn lại giữ cho ăn vặt. Việc làm quà để kênh bán Tết tự lo.',
  takeaway:'Dồn tiền vào việc vừa đông người vừa đang được phục vụ kém; chia đều là không chọn.',
  apply:'Liệt kê hai hoặc ba việc khách thuê sản phẩm của bạn. Ước lượng số người và mức chưa thoả mãn của từng việc, rồi nói trong 60 giây bạn dồn tiền vào đâu.',
  mistakes:['Chia đều ngân sách cho mọi việc để không làm nhóm nào phật ý.','Chỉ nhìn việc đông người nhất mà bỏ qua mức khách đã hài lòng với lựa chọn hiện có.'],
  q:[
  { type:'mcq', stem:'Đoán trước: chia đều 200 triệu cho mỗi việc có vấn đề gì?',
    options:[{k:'a',t:'Chia đều khiến kế toán khó theo dõi chi phí theo từng nhóm khách và từng kênh'},{k:'b',t:'Không có vấn đề lớn, vì công bằng là cách an toàn khi chưa chắc chắn'},
             {k:'c',t:'Không việc nào đủ tiếng nói, và tiền đổ cả vào việc đã được làm tốt'},{k:'d',t:'Quảng cáo quà biếu sẽ tốn hơn nên 200 triệu là thiếu'}],
    answer:'c', why:{a:'Theo dõi chi phí không phải vấn đề chiến lược.',
      b:'Chia đều trông an toàn nhưng thực chất là tránh quyết định.',
      c:'Đúng. Tiền rải mỏng và một phần rơi vào việc khách đã hài lòng với lựa chọn khác.',
      d:'Chi phí mỗi việc chưa được biết; vấn đề là cách chia, không phải số tiền.'} },
  { type:'mcq', stem:'Bạn là trưởng thương hiệu. Với dữ liệu 500 người, bạn chọn phân bổ nào?',
    options:[{k:'a',t:'Dồn phần lớn vào bữa sáng vội, giữ một phần cho ăn vặt, để quà cho kênh Tết'},{k:'b',t:'Chia đều 200 triệu mỗi việc như giám đốc đề xuất ban đầu cho công bằng'},
             {k:'c',t:'Dồn hết vào quà biếu vì biên lợi nhuận hộp quà cao nhất'},{k:'d',t:'Dồn hết vào ăn vặt vì thị trường snack là lớn nhất'}],
    answer:'a', why:{a:'Đúng. Bữa sáng vừa đông người (50%) vừa chưa được phục vụ tốt (7/10).',
      b:'Rải mỏng cho cả việc nhỏ và việc khách đã hài lòng.',
      c:'Biên lãi cao nhưng chỉ 15% khách và mức chưa thoả mãn thấp nhất.',
      d:'Thị trường snack lớn nhưng khách đã khá hài lòng (4/10) — khó chen.'} },
  { type:'calc', stem:'Ngân sách 600 triệu, dồn 70% cho việc bữa sáng vội. Số tiền cho việc này là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:420, tol:0.5, wrong:[[180,'NHAM_TI_LE_ROI'],[200,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI','SAI_TINH_TOAN'],
    steps:['Ngân sách bữa sáng = 600 × 70%.','= <b>420 triệu đồng</b>.'] },
  { type:'calc', stem:'Trong 500 người mua, 250 người thuê bánh cho bữa sáng vội. Tỉ lệ này là bao nhiêu phần trăm?',
    unit:'%', ans:50, tol:0.1, wrong:[[35,'SAI_MAU_SO'],[200,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = 250 ÷ 500.','= <b>50%</b>.'] },
  { type:'mcq', stem:'Một ứng dụng đặt xe thấy khách thuê nó cho: đi làm hằng ngày (đông, khá hài lòng) và đưa bố mẹ già đi khám (ít, rất chưa hài lòng). Nhận định nào hợp lý?',
    options:[{k:'a',t:'Bỏ qua việc đưa bố mẹ đi khám vì số người quá ít, không đáng đầu tư'},{k:'b',t:'Việc đưa bố mẹ đi khám có thể là cửa ngách đáng thử'},
             {k:'c',t:'Dồn hết vào đi làm hằng ngày vì số đông luôn thắng trong mọi trường hợp'},{k:'d',t:'Tách riêng một thương hiệu mới cho người già ngay lập tức'}],
    answer:'b', why:{a:'Số ít nhưng rất chưa hài lòng có thể là chỗ dễ thắng và giữ khách.',
      b:'Đúng. Việc nhỏ mà chưa ai làm tốt là cửa ngách; thử nhỏ để kiểm chứng.',
      c:'Việc đông nhưng đã được làm khá tốt thì khó tạo khác biệt.',
      d:'Nhảy thẳng tới thương hiệu mới trước khi thử là quá sớm.'} },
  { type:'mcq', stem:'Vì sao cần đo "mức chưa thoả mãn" bên cạnh số người có việc?',
    options:[{k:'a',t:'Vì con số chưa thoả mãn luôn chính xác hơn con số quy mô thị trường'},{k:'b',t:'Vì khách chưa hài lòng thường có thu nhập cao hơn khách đã hài lòng'},
             {k:'c',t:'Vì chỉ số này bắt buộc phải có trong báo cáo cho ban giám đốc'},{k:'d',t:'Vì việc đông người mà đã làm tốt thì khách ít lý do đổi sang bạn'}],
    answer:'d', why:{a:'Cả hai đều là ước lượng; cần dùng cùng nhau.',
      b:'Không có quan hệ tất yếu với thu nhập.',
      c:'Không phải yêu cầu báo cáo; nó là công cụ ra quyết định.',
      d:'Đúng. Khoảng trống giữa việc và lựa chọn hiện có mới là chỗ khách sẵn lòng đổi.'} },
  { type:'mcq', stem:'Sau quý đầu, doanh số bữa sáng tăng nhưng nhóm ăn vặt giảm nhẹ. Nên phản ứng thế nào?',
    options:[{k:'a',t:'Quay lại chia đều ngay để không mất thêm khách ăn vặt'},{k:'b',t:'Xem mức giảm có nhỏ hơn phần tăng và có do cắt tiền hay không'},
             {k:'c',t:'Kết luận chiến lược tập trung đã thất bại và dừng quảng cáo bữa sáng để rà soát lại từ đầu'},{k:'d',t:'Chuyển toàn bộ ngân sách sang ăn vặt để bù phần giảm'}],
    answer:'b', why:{a:'Phản ứng theo một con số giảm mà chưa so với phần tăng.',
      b:'Đúng. Tập trung luôn có đánh đổi; cần xem tổng kết quả và nguyên nhân trước khi đổi.',
      c:'Doanh số bữa sáng tăng — kết luận thất bại là vội.',
      d:'Đảo ngược toàn bộ vì một tín hiệu nhỏ là mất đi chỗ đang thắng.'} }
  ] }

] });
